 const pipeline=[['SCAN',val(d.checkedCoins)],['FORECAST',val(d.forecastAvailable)],['ADMITTED',val(d.admittedForecasts)],['CALIBRATED',val(d.totalCalibratedHorizons)],['PRIMARY CAND.',val(d.standardCandidates)],['RESEARCH CAND.',val(d.explorationCandidates)],['PRIMARY TRADE',val(d.standardTrades)],['RESEARCH TRADE',val(d.explorationTrades)+val(d.coverageProbes)]];
