 (rc.length?sec('Letzte Research Abschlüsse')+rc.slice(0,6).map(x=>'<div class="panel"><b>'+E(String(x.symbol||'').replace('USDT','/USDT'))+' · '+E(mode(x.entryMode))+'</b><div class="ms">'+E(x.closeReason||'geschlossen')+' · '+MONEY(x.realizedNetPnlQuote)+' · '+pct(x.realizedReturnPct)+'</div></div>').join(''):'')+
 '</section>'
