function MPCT(x){const n=NUM(x);return Number.isFinite(n)?(n*100).toFixed(1)+'%':'—'}
function MAGE(ts){const t=NUM(ts);if(!Number.isFinite(t))return '—';const m=Math.max(0,Math.floor((Date.now()-t)/60000));return m<60?m+'m':m<1440?Math.floor(m/60)+'h '+(m%60)+'m':Math.floor(m/1440)+'d'}
function MHOLD(ms){const n=NUM(ms);if(!Number.isFinite(n)||n<0)return '—';const m=Math.floor(n/60000);return m<60?m+'m':Math.floor(m/60)+'h '+(m%60)+'m'}
function MEMEPRICE(x){const n=NUM(x);if(!Number.isFinite(n)||n<=0)return '—';if(n>=1)return '$'+n.toFixed(3);if(n>=.01)return '$'+n.toFixed(5);if(n>=.0001)return '$'+n.toFixed(7);return '$'+n.toPrecision(5)}
function memeKey(chain,address){return String(chain||'').toLowerCase()+':'+String(address||'').toLowerCase()}
function memeRadar(){return S.health?.memecoinRadar||{}}
function memeWallets(){return S.health?.specialistWallets?.wallets||{}}
function memeSelectedWallet(){const ws=memeWallets();return ws[MEME_WALLET]||ws.W4_MEME_SCOUT||{}}
function memeRangeMs(){return {H24:24*3600000,'7D':7*86400000,'30D':30*86400000,ALL:Infinity}[MEME_RANGE]||7*86400000}
function memeClosedRange(rows){const ms=memeRangeMs();if(!Number.isFinite(ms))return rows||[];const cut=Date.now()-ms;return (rows||[]).filter(x=>N(x.closedAt)>=cut)}
function memeSeries(wallet){
 const closed=memeClosedRange((wallet.recentClosed||[]).slice().sort((a,b)=>N(a.closedAt)-N(b.closedAt)));
 let acc=0;const ys=[0];for(const x of closed){acc+=N(x.realizedNetPnlQuote);ys.push(acc)}
 ys.push(acc+N(wallet.unrealizedPnlQuote));return ys
}
function lineSvg(values,small=false){
 const a=(values||[]).map(Number).filter(Number.isFinite);if(a.length<2)a.push(a[0]||0);
 const w=small?70:640,h=small?24:120,p=small?2:8;let lo=Math.min(...a),hi=Math.max(...a);if(hi-lo<1e-9){hi+=1;lo-=1}
 const pts=a.map((v,i)=>{const x=p+(w-2*p)*(i/Math.max(1,a.length-1));const y=h-p-(h-2*p)*((v-lo)/(hi-lo));return x.toFixed(1)+','+y.toFixed(1)}).join(' ');
 if(small)return '<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><polyline points="'+pts+'" fill="none" stroke="'+(a[a.length-1]>=a[0]?'#32f0ae':'#ff6174')+'" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>';
 const area=pts+' '+(w-p)+','+(h-p)+' '+p+','+(h-p);
 return '<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none"><defs><linearGradient id="memeGrad" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#31efad" stop-opacity=".42"/><stop offset="1" stop-color="#31efad" stop-opacity="0"/></linearGradient></defs><polygon points="'+area+'" fill="url(#memeGrad)"/><polyline class="memeLine" points="'+pts+'"/></svg>'
}
function memeRadarMap(){const m=new Map();for(const r of memeRadar().rows||[])m.set(memeKey(r.chainId,r.tokenAddress),r);return m}
function memeAvgHold(closed){const a=(closed||[]).map(x=>N(x.closedAt)-N(x.openedAt)).filter(x=>Number.isFinite(x)&&x>=0);return a.length?a.reduce((s,x)=>s+x,0)/a.length:null}
function memeBestWorst(closed){const xs=(closed||[]).filter(x=>Number.isFinite(NUM(x.realizedReturnPct)));if(!xs.length)return {best:null,worst:null};return {best:xs.reduce((a,b)=>N(a.realizedReturnPct)>N(b.realizedReturnPct)?a:b),worst:xs.reduce((a,b)=>N(a.realizedReturnPct)<N(b.realizedReturnPct)?a:b)}}
function memeKpi(icon,label,value,sub,cls=''){return '<div class="kpi '+cls+'"><div class="kpiIcon">'+icon+'</div><span>'+E(label)+'</span><b>'+value+'</b><div class="ms">'+E(sub||'')+'</div></div>'}
